def group_tuples(tuples_list):
    # Initialize an empty dictionary to store grouped tuples
    grouped_dict = {}
    # Iterate over each tuple in the list
    for tup in tuples_list:
        if tup[0] in grouped_dict:
            # If the first element is already a key, append the second element to its value
            grouped_dict[tup[0]].append(tup[1])
        else:
            # Otherwise, initialize a new key with a list containing the second element
            grouped_dict[tup[0]] = [tup[1]]

    # Convert the dictionary to a list of tuples
    result = [(key, *values) for key, values in grouped_dict.items()]

    # Ensure the remaining elements that were not grouped are included
    for tup in tuples_list:
        if tup[0] not in [item[0] for item in result] and (tup[0], tup[1]) not in result:
            # Add the tuple directly to the result as a new tuple
            result.append((tup[0], tup[1]))
        elif tup[0] in [item[0] for item in result] and (tup[0], tup[1]) not in result:
            # If the first element is already in the result but the specific tuple is not, add it to the correct group
            for i, item in enumerate(result):
                if item[0] == tup[0]:
                    result[i] = (tup[0], *result[i][1:], tup[1])

    return result

